[metadata] {"type": "create", "filePath": "/workspace/repo/metadata-ingestion/src/datahub/utilities/caller_context.py", "content": """"Auto-detect the tool or environment that invoked the DataHub CLI.

Detection uses a tiered approach, from most to least authoritative:

1. An explicit ``DATAHUB_CALLER`` environment variable override.
2. Known signatures in the CLI process's own environment (AI coding tools,
   CI systems, etc.).
3. The parent process's environment, matched against the same signatures.
4. Process-tree heuristics based on ancestor process names.

The public entry point :func:`identify_caller` never raises and always returns
a short label string suitable for embedding in a User-Agent header.
"""

from __future__ import annotations

import functools
import os
import platform
import subprocess
from typing import Dict, List, Optional

# Environment-variable signatures, in priority order. AI coding tools are listed
# before CI systems so that, when a parent environment contains several matching
# signatures at once, the more specific tool wins (see _match_signatures).
#
# Keys without an "=" are matched by key presence (the CLI only needs to know the
# variable exists). Keys containing "=" would be matched as an exact "KEY=value"
# substring.
_CALLER_SIGNATURES: Dict[str, str] = {
    "CLAUDECODE": "claude-code",
    "CURSOR_TRACE_ID": "cursor",
    "LANGCHAIN_TRACING_V2": "langchain",
    "LANGSMITH_API_KEY": "langchain",
    "LANGGRAPH_API_URL": "langgraph",
    "GITHUB_ACTIONS": "github-actions",
    "JENKINS_URL": "jenkins",
}

# Interactive shells that indicate the CLI was launched directly from a terminal.
_SHELLS = frozenset({"bash", "zsh", "fish", "sh", "dash", "tcsh", "ksh"})

# Keep subprocess probes short so caller detection never noticeably delays the CLI.
_SUBPROCESS_TIMEOUT = 2.0

# Guardrails on the returned label so it is always safe to embed in a header.
_MAX_LABEL_LENGTH = 200


def _is_truthy(value: Optional[str]) -> bool:
    if value is None:
        return False
    return value.strip().lower() not in ("", "0", "false", "no", "off")


def _match_signatures(env_text: str) -> Optional[str]:
    """Return the label of the first known signature present in ``env_text``.

    ``env_text`` is space- or newline-separated ``KEY=value`` text (e.g. the
    contents of ``/proc/<pid>/environ`` with null bytes replaced by newlines).
    """
    for key, label in _CALLER_SIGNATURES.items():
        if "=" in key:
            if key in env_text:
                return label
        elif f"{key}=" in env_text:
            return label
    return None


def _read_parent_env_linux(ppid: int) -> Optional[str]:
    try:
        with open(f"/proc/{ppid}/environ", "rb") as f:
            data = f.read()
    except (PermissionError, FileNotFoundError):
        return None
    return data.decode("utf-8", errors="replace").replace("\0", "\n")


def _read_parent_env_macos(ppid: int) -> Optional[str]:
    try:
        result = subprocess.run(
            ["ps", "eww", "-p", str(ppid), "-o", "command="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout


def _get_full_command(pid: int) -> Optional[str]:
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "command="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout.strip()


def _get_process_name(pid: int) -> Optional[str]:
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "comm="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    name = os.path.basename(result.stdout.strip())
    # The Gradle daemon runs as a bare "java" process; disambiguate it via the
    # full command line so it is reported as "gradle" rather than "java".
    if name == "java":
        full_command = _get_full_command(pid)
        if full_command and "GradleDaemon" in full_command:
            return "gradle"
    return name


def _get_parent_pid(pid: int) -> Optional[int]:
    if pid == 1:
        return None
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "ppid="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    try:
        return int(result.stdout.strip())
    except ValueError:
        return None


def _get_ancestor_chain(max_depth: int = 4) -> List[str]:
    chain: List[str] = []
    pid = os.getppid()
    while len(chain) < max_depth:
        name = _get_process_name(pid)
        if name is None:
            break
        chain.append(name)
        parent = _get_parent_pid(pid)
        if parent is None:
            break
        pid = parent
    return chain


def _detect_from_current_env() -> Optional[str]:
    env = os.environ
    if _is_truthy(env.get("CLAUDECODE")):
        return "claude-code"
    if "CURSOR_TRACE_ID" in env:
        return "cursor"
    if _is_truthy(env.get("LANGCHAIN_TRACING_V2")):
        return "langchain"
    if "LANGSMITH_API_KEY" in env:
        return "langchain"
    if "LANGGRAPH_API_URL" in env:
        return "langgraph"
    if _is_truthy(env.get("GITHUB_ACTIONS")):
        return "github-actions"
    if "JENKINS_URL" in env:
        return "jenkins"
    if env.get("CI", "").strip().lower() in ("true", "1", "yes"):
        return "ci"
    return None


def _detect_from_process_tree() -> str:
    chain = _get_ancestor_chain()
    if not chain:
        return "unknown"
    lowered = [name.lower() for name in chain]
    if any("cursor" in name for name in lowered):
        return "cursor"
    if any("claude" in name for name in lowered):
        return "claude-code"
    if lowered[0] in _SHELLS:
        return "terminal"
    return chain[0]


def _identify_caller_inner() -> str:
    # Tier 1: explicit override.
    override = os.environ.get("DATAHUB_CALLER")
    if override:
        return override

    # Tier 2: signatures in the CLI's own environment.
    current = _detect_from_current_env()
    if current:
        return current

    # Tier 3: the parent process's environment.
    system = platform.system()
    ppid = os.getppid()
    parent_env: Optional[str] = None
    if system == "Linux":
        parent_env = _read_parent_env_linux(ppid)
    elif system == "Darwin":
        parent_env = _read_parent_env_macos(ppid)
    if parent_env:
        label = _match_signatures(parent_env)
        if label:
            return label

    # Tier 4: process-tree heuristics.
    return _detect_from_process_tree()


